const html       = $input.first().json.data;
const modo       = $('Config').first().json.modo       || 'incremental';
const dataLimite = new Date($('Config').first().json.data_limite || '2025-06-01');

// Extrai todos os links .xlsx da página
const regex = /href\s*=\s*["']([^"']+\.xlsx)["']/gi;
let m; const raw = [];
while ((m = regex.exec(html)) !== null)
  raw.push(m[1].replace(/&amp;/g, '&'));

const links = [...new Set(raw)].filter(u => u.toLowerCase().includes('revendas_lpc_'));
if (links.length === 0) throw new Error('[ANP] Nenhum link revendas_lpc_ encontrado.');

let targets;

if (modo === 'backfill') {
  // Pega TODOS os arquivos a partir da data_limite, do mais antigo para o mais novo
  targets = links
    .filter(u => {
      const d = u.match(/(\d{4})-(\d{2})-(\d{2})/);
      if (!d) return false;
      return new Date(d[1], d[2]-1, d[3]) >= dataLimite;
    })
    .sort(); // crescente = mais antigo primeiro
  if (targets.length === 0)
    throw new Error('[ANP] Nenhum arquivo encontrado após filtro de data.');
} else {
  // Incremental: apenas o arquivo mais recente
  targets = [links.sort().reverse()[0]];
}

console.log(`[ANP] Modo: ${modo} | Arquivos a processar: ${targets.length}`);

return targets.map(url => ({ json: {
  file_name  : url.split('/').pop(),
  url,
  modo,
  data_limite: $('Config').first().json.data_limite
}}));

