const items = $input.all();
if (items.length > 0) {
  const headers = Object.keys(items[0].json);
  console.log('[ANP DEBUG] Headers reais do XLSX:', JSON.stringify(headers));
  console.log('[ANP DEBUG] Primeira linha:', JSON.stringify(items[0].json));
  console.log('[ANP DEBUG] Total de itens:', items.length);
} else {
  console.log('[ANP DEBUG] extractFromFile retornou VAZIO.');
}
return items; // passa adiante sem modificar

// ─── Metadados do arquivo atual (do loop) ───────────────────────────────────
const loopItem   = $('Loop de Arquivos').item.json;
const fileName   = loopItem.file_name;
const modo       = loopItem.modo       || 'incremental';
const dataLimite = new Date(loopItem.data_limite || '2025-06-01');

// ─── Helpers ─────────────────────────────────────────────────────────────────
const norm = (s) => String(s||'').trim().toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .replace(/\s+/g,' ');

const toISO = (v) => {
  if (!v && v !== 0) return null;
  if (typeof v === 'number')
    return new Date(Math.round((v - 25569) * 864e5)).toISOString().split('T')[0];
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.substring(0,10);
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [d,mo,y] = s.split('/');
    return `${y}-${mo.padStart(2,'0')}-${d.padStart(2,'0')}`;
  }
  return null;
};

const toNum = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).trim().replace(/\./g,'').replace(',','.'));
  return isNaN(n) ? null : n;
};

// ─── Passo 1: extrair array de linhas brutas ─────────────────────────────────
// rawData:true → cada item chega como { row: [v0, v1, ...] }
const allItems = $input.all();

const rawRows = allItems.map(item => {
  const obj = item.json;
  if (Array.isArray(obj.row)) return obj.row;
  // fallback: chaves numéricas "0","1","2"...
  const numKeys = Object.keys(obj).filter(k => !isNaN(Number(k)));
  if (numKeys.length > 0)
    return numKeys.sort((a,b) => Number(a)-Number(b)).map(k => obj[k]);
  return Object.values(obj);
});

// ─── Passo 2: detectar linha de header real ───────────────────────────────────
// Âncora: linha que contém a célula com valor normalizado === 'cnpj'
// (mais confiável que 'produto' — CNPJ está sempre na coluna A)
let headerRowIdx = -1;
let headers      = [];

for (let i = 0; i < rawRows.length; i++) {
  const row = rawRows[i];
  if (!Array.isArray(row)) continue;
  if (row.some(cell => norm(String(cell ?? '')) === 'cnpj')) {
    headerRowIdx = i;
    headers      = row.map(cell => norm(String(cell ?? '')));
    break;
  }
}

if (headerRowIdx === -1) {
  console.error('[ANP] ERRO: linha de header (CNPJ) não encontrada.');
  console.error('[ANP] Primeiras 12 linhas:', JSON.stringify(rawRows.slice(0,12)));
  return [];
}

console.log(`[ANP] Header na linha ${headerRowIdx}:`, JSON.stringify(headers));

// ─── Passo 3: mapa de índices pelo nome exato das colunas da ANP ─────────────
// Estrutura real confirmada pelo usuário:
// CNPJ | RAZÃO | FANTASIA | ENDEREÇO | NÚMERO | COMPLEMENTO | BAIRRO | CEP |
// MUNICÍPIO | ESTADO | BANDEIRA | PRODUTO | UNIDADE DE MEDIDA | PREÇO DE REVENDA | DATA DA COLETA
const idx = (name) => headers.indexOf(norm(name));

const I = {
  cnpj      : idx('cnpj'),
  razao     : idx('razao'),                  // "RAZÃO" → norm → "razao"
  fantasia  : idx('fantasia'),
  endereco  : idx('endereco'),               // "ENDEREÇO" → norm → "endereco"
  numero    : idx('numero'),                 // "NÚMERO" → norm → "numero"
  compl     : idx('complemento'),
  bairro    : idx('bairro'),
  cep       : idx('cep'),
  municipio : idx('municipio'),              // "MUNICÍPIO" → norm → "municipio"
  estado    : idx('estado'),
  bandeira  : idx('bandeira'),
  produto   : idx('produto'),
  unidade   : idx('unidade de medida'),
  preco     : idx('preco de revenda'),       // "PREÇO DE REVENDA" → norm → "preco de revenda"
  data      : idx('data da coleta'),
};

console.log('[ANP] Índices:', JSON.stringify(I));

// Valida campos obrigatórios
const obrigatorios = ['cnpj','produto','preco','data'];
const faltando = obrigatorios.filter(k => I[k] === -1);
if (faltando.length > 0) {
  console.error('[ANP] ERRO: campos obrigatórios não encontrados:', faltando);
  console.error('[ANP] Headers normalizados encontrados:', JSON.stringify(headers));
  return [];
}

// ─── Passo 4: processar linhas de dados ───────────────────────────────────────
const cel = (row, i) => (i >= 0 && row[i] !== undefined && row[i] !== null) ? row[i] : null;
const str = (row, i) => { const v = cel(row, i); return v !== null ? String(v).trim() : null; };

const result = [];

for (let i = headerRowIdx + 1; i < rawRows.length; i++) {
  const row = rawRows[i];
  if (!Array.isArray(row) || row.every(c => c === null || c === '')) continue;

  const isoDate = toISO(cel(row, I.data));
  if (!isoDate) continue;
  if (modo === 'backfill' && new Date(isoDate) < dataLimite) continue;

  result.push({ json: {
    cnpj_revenda   : str(row, I.cnpj),
    razao_social   : str(row, I.razao),
    nome_fantasia  : str(row, I.fantasia),
    endereco       : str(row, I.endereco),
    numero         : str(row, I.numero),
    complemento    : str(row, I.compl),
    bairro         : str(row, I.bairro),
    cep            : str(row, I.cep),
    municipio      : str(row, I.municipio),
    estado_sigla   : str(row, I.estado),
    bandeira       : str(row, I.bandeira),
    produto        : str(row, I.produto),
    unidade_medida : str(row, I.unidade),
    preco_revenda  : toNum(cel(row, I.preco)),
    data_coleta    : isoDate,
    arquivo_origem : fileName
  }});
}

console.log(`[ANP] ${fileName}: ${rawRows.length - headerRowIdx - 1} linhas → ${result.length} válidas`);
return result;

// Lê arquivo_origem do primeiro item — todos têm o mesmo valor
const fileName    = $input.first().json.arquivo_origem;
const totalLinhas = $input.all().length;
return [{ json: { file_name: fileName, total_linhas: totalLinhas } }];

